entries[207165] = { ["name"] = "Bandolier of Twisted Blades", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Agility\nUse: Plunge a twisted blade into your target, dealing 60632 Physical damage. After 3 sec, the blade ignites with Shadowflame and returns to you, dealing 148548 Shadowflame damage split between the target and all enemies in its path.\n\nDamage increased per enemy struck, up to 5. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[207166] = { ["name"] = "Cataclysmic Signet Brand", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 [Agility or Strength]\nEquip: Your melee attacks and abilities have a chance to viciously brand your target, dealing [ 33315 * ((1.2)^(9))] Fire damage over 6 sec, and grant you Firestarter , stacking up to 15 times. Damage increased per stack to a maximum of [ 33315 * ((1.2)^(5))].\n\nWhile above 5 stacks, also deals 50% of its damage to you. At 15 stacks, enemies near your target suffer 10% of the damage dealt split between them. Firestarter decays every 3 sec while out of combat and fades entirely after 15 sec.\nSell Price:" }
entries[207167] = { ["name"] = "Ashes of the Embersoul", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 616 Haste\nUse: Draw power from the remnants of the Embersoul, gaining 4682 Primary Stat for 20 sec, decaying every 2 sec. Once this effect ends, become Burned Out, losing 617 Haste for 60 sec before recovering.\n\nWhen circumstances are dire your soul ignites, granting this bonus again without decaying. This effect may only occur once per combat. (2 Min Cooldown)\nSell Price:" }
entries[207168] = { ["name"] = "Pip's Emerald Friendship Badge", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 [Agility or Strength or Intellect]\nEquip: Join the Dream Team, gaining ( 2870 / 12) of Pip's Mastery, Urctos's Versatility, or Aerwynn's Critical Strike based on your current Best Friend.\n\nYour spells and abilities have a chance to tag in a random new Best Friend, granting you their passive bonus and empowering it to 2870 before diminishing over 12 sec. (12s cooldown)\nSell Price:" }
entries[207169] = { ["name"] = "Branch of the Tormented Ancient", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Strength\nUse: Summon 4 roots to draw on their power for 15 sec, slowing you by 15% per root. Your next 4 melee abilities each sever a root, dealing 77369 additional Shadowflame damage split between nearby enemies.\n\nDamage increased per enemy struck, up to 5. (1s cooldown) (2 Min, 30 Sec Cooldown)\nSell Price:" }
entries[207170] = { ["name"] = "Smoldering Seedling", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Intellect\nUse: Replant the Seedling and attempt to put out its flames for 12 sec. Healing the Seedling also heals up to 5 injured allies for the same amount, split evenly. Healing is increased for each ally until 535280 additional healing is provided.\n\nIf the Seedling is still alive after 12 sec, receive 639 Mastery for 10 sec as thanks. (2 Min Cooldown)\nSell Price:" }
entries[207171] = { ["name"] = "Blossom of Amirdrassil", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 616 Haste\nEquip: Healing an ally below 80% health grants them Blossom of Amirdrassil, healing for ( 42916 * 6) over 6 sec. This effect may occur once per minute.\n\nIf the target is above 95% health when this effect expires, the Blossom spreads to 3 injured allies to heal for ( 21457 * 6) over 6 sec. If the target is not fully healed, the Blossom blooms to absorb 386242 damage instead. (1m cooldown)\n\"A bright future from the ashes.\"\nSell Price:" }
entries[207172] = { ["name"] = "Belor'relos, the Suncaller", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Intellect\nUse: Unleash a solar maelstrom, slowing yourself and nearby enemies before erupting in flames after 2 sec to deal 395581 Fire damage split between all enemies and 197791 Fire damage to you over 12 sec.\n\nCastable while moving. Damage increased per enemy struck, up to 5. (2 Min Cooldown)\n\"Enae elen'relos!\"\nSell Price:" }
entries[207173] = { ["name"] = "Gift of Ursine Vengeance", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 [Agility or Strength]\nEquip: Swipe at a the nearest enemy for 8612 Physical damage and gain 1 stack of Rising Rage whenever you or an ally takes damage, granting 8 Primary Stat and stacking up to 30 times. This effect may occur every 3 sec.\n\nAt 30 stacks of Rising Rage , gain Fury of Urctos for 8 sec before consuming them, counterattacking all blows and regenerating 13482 health every 1 sec.\n\nValid only for tank specializations.\nSell Price:" }
entries[207174] = { ["name"] = "Fyrakk's Tainted Rageheart", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 616 Versatility\nEquip: Deal 948 Shadowflame damage to you and nearby enemies every 3 sec while in combat.\nUse: Give in to the Rageheart, absorbing 605710 damage for 20 sec. Suffer 54515 Shadowflame damage and lash out at a nearby enemy every 2 sec for 10 sec to deal 37884 Shadowflame damage split between nearby enemies.\n\nDamage increased per enemy struck, up to 5. (1 Min, 30 Sec Cooldown)\n\"A fate of twisted blood.\"\nSell Price:" }
entries[207175] = { ["name"] = "Coiled Serpent Idol", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 [Agility or Strength]\nEquip: Your critical strikes have a chance to summon a lava serpent to attack your target for 10 sec. The serpent spews a lava bolt every 2 sec, dealing 8709 Volcanic damage. Every third summoning, call forth three serpents instead.\n\nIf the target dies, the serpent enrages to deal 16129 Volcanic damage to up to 8 nearby enemies.\nSell Price:" }
