entries[208307] = { ["name"] = "Verdant Combatant's Medallion", ["text"] = "Binds when equipped\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+205 [Agility or Strength or Intellect]\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[208308] = { ["name"] = "Verdant Combatant's Insignia of Alacrity", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+ 291 Haste\nEquip: Your spells and abilities have a chance to grant 457 primary stat for 20 sec.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[208309] = { ["name"] = "Verdant Combatant's Emblem", ["text"] = "Binds when equipped\nUnique-Equipped\nTrinket\n+205 [Agility or Strength or Intellect]\nUse: Increases maximum health by 26226 for 15 sec. (2 Min Cooldown)\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
