entries[208572] = { ["name"] = "Azure Worldchiller", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"In the corners of Azeroth, stories are told of a dreaded dragon who swept a pall of torment over the land. In some versions of this story, his fiery presence brought cataclysmic death and destruction worldwide. In other versions, he is blue.\"\nDrop:\nDoomwalker\nZone:\nTanaris" }
entries[208576] = { ["name"] = "Thriving Restoration Mote", ["text"] = "Quest Item\n\"A mote capable of restoring the Tattered Dreamleaf a large amount.\"" }
entries[208577] = { ["name"] = "Symbiotic Glowspore Grip", ["text"] = "Binds when picked up\n\"This adaptive grip is capable of withstanding immense amounts of fluctuating shadowflame. Crafted in tandem with Master Leatherworker Erden.\"" }
entries[208578] = { ["name"] = "Concentrated Sophic Vellum", ["text"] = "Binds when picked up\n\"This vellum details incantations that can guide shadowflame away from the wielder. Crafted in tandem with Master Enchantress Shalasar.\"" }
entries[208581] = { ["name"] = "Radiant Fleck of Ash", ["text"] = "Binds when picked up\n\"Coarse ash that finds itself binding to various pieces of equipment. Can only be removed by disenchanting.\"" }
entries[208587] = { ["name"] = "Budding Restoration Mote", ["text"] = "Binds when picked up\n\"A mote capable of restoring the Tattered Dreamleaf a small amount.\"" }
entries[208588] = { ["name"] = "Burgeoning Restoration Mote", ["text"] = "Binds when picked up\n\"A mote capable of restoring the Tattered Dreamleaf a moderate amount.\"" }
entries[208592] = { ["name"] = "Rune of Shadowbinding", ["text"] = "Binds when picked up\n\"A powerful rune that strengthens as it's damaged. Crafted in tandem with Master Scribe Lydiara.\"" }
entries[208593] = { ["name"] = "Shadowed Dreamleaf", ["text"] = "Binds when picked up\n\"An astoundingly firm, leathery blade of foliage. Found throughout the Emerald Dream.\"" }
entries[208595] = { ["name"] = "Taut Tethercoil", ["text"] = "Binds when picked up\n\"An irritated root that adapts its power to the elements around it.\"" }
entries[208597] = { ["name"] = "Eadweard's Notes", ["text"] = "Binds when picked up\nUse: Place a stack of various notes Eadward has collected relevant to Shadowflame. Party and raid members are also able to browse the notes collected by the historian who placed the them.\n\nThe stack of notes lasts for 5 min.\n\"A stack of journals that detail anything important to the crafting of Fyr'alath.\"" }
entries[208598] = { ["name"] = "Eve's Ghastly Rider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location. During Hallow's End the cast time is instant.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The preferred transportation of the Fenlow family (especially during Hallow's End).\"\nTrading Post" }
entries[208599] = { ["name"] = "Verdant Dream Seed", ["text"] = "Quest Item\n\"A glowing seed from the Dream's flora. It pulses faintly with wild magic.\"" }
entries[208600] = { ["name"] = "Chromie's Timespun Shoulderpads", ["text"] = "Cosmetic\nBinds to Warband\nShoulder Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208606] = { ["name"] = "Somnagora's Heart", ["text"] = "Binds when picked up\nUnique\nRequires level 10 to 70 ( 70)\n\"A sap-covered Mandragora heart. It smells like peaches and fresh soil.\"" }
entries[208613] = { ["name"] = "High Scholar's Drape", ["text"] = "Cosmetic\nBinds to Warband\nBack\n1 Armor\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208614] = { ["name"] = "Augury of the Primal Flame", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 616 Critical Strike\nEquip: Your spells and abilities have a low chance to grant Annihilating Flame for 20 sec, causing your critical strikes to deal 50% additional damage as Fire split between nearby enemies. The Flame may deal [ 97891 * (1 + Versatility)] total damage before fading, further increased by critical strikes.\n\nDamage and cap increased per enemy struck, up to 5.\n\"A vision of endless flame.\"\nSell Price:" }
entries[208615] = { ["name"] = "Nymue's Unraveling Spindle", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Intellect\nUse: Channel to unravel your target's essence, dealing 247877 Nature damage over 3 sec and granting you up to 2790 Mastery for 18 sec.\n\nDamage increased by 30% against immobilized targets. (2 Min Cooldown)\nSell Price:" }
entries[208616] = { ["name"] = "Dreambinder, Loom of the Great Cycle", ["text"] = "Binds when picked up\nTwo-Hand Staff\n690 - 934 Damage Speed 3.60\n(225.6 damage per second)\n+2,666 Intellect\n+2,128 Stamina\n+ 581 Haste\n+ 282 Mastery\nDurability 120 / 120\nUse: Weave a web of dreams beneath your target after 2 sec, dealing 80339 Nature damage split between all enemies within 8 yds. Your target is immobilized for 4 sec while additional enemies are slowed by 80%. Less effective against enemy players.\n\nDamage increased per enemy struck, up to 5. (2 Min Cooldown)\nSell Price:" }
entries[208617] = { ["name"] = "Ebon Blade Commendation Badge", ["text"] = "Binds when picked up\nUse: Increases your Knights of the Ebon Blade reputation by 260." }
entries[208619] = { ["name"] = "The Tragedy of Erinethria", ["text"] = "Binds when picked up\nUnique\n\"May her name, and her lesson, be ever remembered.\"\n<Right Click to Read>\nSell Price:" }
