entries[208644] = { ["name"] = "Lasher Plant Matter", ["text"] = "Binds when picked up\nUnique (5)\nUse: Combine with Tel'Abim Bananas and Turtle Eggshell Shards to form what will become fertilizer, given some patience.\n\"Combined with some other key ingredients, this is the perfect foundation for a hearty fertilizer.\"" }
entries[208645] = { ["name"] = "Unstable Faerie Dust", ["text"] = "Binds when picked up\nUnique (3)\n\"The dust pulses irregularly with barely-contained energy.\"" }
entries[208646] = { ["name"] = "Combined Fertilizer Ingredients", ["text"] = "Duration: 3 days (real time)\n\"Tucked away in a warm spot in your bags, all you have to do is wait.\"" }
entries[208647] = { ["name"] = "Primed Emerald Dream Fertilizer", ["text"] = "Binds when picked up\n\"Completely combined, it's now ready to be added to the soil.\"" }
