entries[208662] = { ["name"] = "Lightforged Seeker", ["text"] = "Cosmetic\nBinds to Warband\nRanged Bow\n3 - 5 Damage Speed 3.00\n(1.3 damage per second)\nDurability 55 / 55\n\"An ordinary weapon to the Army of the Light, a cursed bane to the demons remaining on Argus.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208663] = { ["name"] = "Ashamane's Vestment of Rebirth", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Ashamane's Vestment of Rebirth.\n\"Worn by the Ashen Druids, these vestments pay homage to the fallen Wild God, Ashamane.\"" }
entries[208664] = { ["name"] = "Ashamane's Blessings of Rebirth", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Ashamane's Blessings of Rebirth.\n\"Engraved with the Mark of the Ashen Druids.\"" }
entries[208665] = { ["name"] = "Webbed Saronite Exoskeleton", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Webbed Saronite Exoskeleton.\n\"The webs of the nerubians aren't just for decor.\"" }
entries[208666] = { ["name"] = "Webbed Saronite Weaponry", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Webbed Saronite Weaponry.\n\"Sharp enough to cut through nerubian silk.\"" }
entries[208667] = { ["name"] = "Nathreza Blasphemer's Flames", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Nathreza Blasphemer's Flames.\n\"Strike fear into any demon's heart with your flame's controlled chaos.\"" }
entries[208668] = { ["name"] = "Nathreza Blasphemer's Glaives", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Nathreza Blasphemer's Glaives.\n\"This aerodynamic design will help chase down any demon.\"" }
entries[208669] = { ["name"] = "Possessed Watcher Guise", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Possessed Watcher Guise.\n\"The spirit inhabiting this armor is great company.\"" }
entries[208670] = { ["name"] = "Arachnophobia Mode", ["text"] = "Binds when picked up\nUnique\nUse: Activate arachnophobia mode." }
entries[208671] = { ["name"] = "Possessed Watcher Arsenal", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Possessed Watcher Arsenal.\n\"The way of the Watcher is silent and deadly.\"" }
entries[208672] = { ["name"] = "Jewels of the Alluring Call", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Jewels of the Alluring Call.\n\"No one can resist temptation.\"" }
entries[208673] = { ["name"] = "Instruments of the Alluring Call", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Instruments of the Alluring Call.\n\"The way of the watcher is silent and deadly.\"" }
entries[208674] = { ["name"] = "Savage Champion's Trophies", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Savage Champion's Trophies.\n\"No beast is a match to our champion.\"" }
entries[208675] = { ["name"] = "Savage Champion's Aggression", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Savage Champion's Aggression.\n\"As pale as the moon, as deadly the fang.\"" }
entries[208676] = { ["name"] = "Sprouted Seedling", ["text"] = "Quest Item\n\"Dug up seed of a violet forget-me-not that has already begun to sprout.\"" }
entries[208677] = { ["name"] = "Eredath Crystal Hammer", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Mace\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\nDurability 50 / 50\n\"A common weapon used by many in the greatest city of the eredar.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208680] = { ["name"] = "Windborne Velocidrake: Hallow's End Armor", ["text"] = "Drakewatcher Manuscript\nBinds when picked up\nUnique\nUse: Unlocks this customization option for the Windborne Velocidrake at the Rostrum of Transformation." }
entries[208683] = { ["name"] = "Arinor Ritual Baton", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Mace\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\nDurability 50 / 50\n\"None of the Arinor groundskeeper ritualists survive, but their tools remain.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208684] = { ["name"] = "Anchorite's Sorrow", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Dagger\n2 - 5 Damage Speed 3.60\n(1.0 damage per second)\nDurability 30 / 30\n\"An anchorite forced to rely on a blade has already failed at least once.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208685] = { ["name"] = "Recovered Kaarinos Blade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\nDurability 50 / 50\n\"Few relics of the lost peaks of Kaarinos remain, but are precious to those who remember that land.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208686] = { ["name"] = "Velenite Claymore", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\nDurability 55 / 55\n\"Once carried by those eredar sworn to Velen's service before darkness came to Argus.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208688] = { ["name"] = "Telaasti Mining Pick", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Axe\n1 - 4 Damage Speed 2.60\n(1.0 damage per second)\nDurability 50 / 50\n\"Few remember the rich mines of the Telaasti Reaches, consumed by the construction of Antorus millennia ago.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[208690] = { ["name"] = "Roottwined Key", ["text"] = "Binds when picked up\nUnique\nRequires level 10 to 70 ( 70)\n\"An odd tangle of roots shaped like a key. What could it unlock?\"" }
entries[208691] = { ["name"] = "Argunite Cluster", ["text"] = "Binds when picked up\n\"A gift from one of Arzaal's allies remaining on Argus. Contains Veiled Argunite and other materials.\"\n<Right Click to Open>" }
entries[208692] = { ["name"] = "Ancient Roottwined Tome", ["text"] = "Binds when picked up\nUnique\nRequires level 10 to 70 ( 70)\n\"What seems to be an ancient herbalist's journal, complete with hand-drawn diagrams of floral anatomy. Vinna would want to see this.\"" }
