entries[208699] = { ["name"] = "Battle Magister's Regalia", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Battle Magister's Regalia.\n\"None were more skilled in the mastery of arcane than the High Elven Magisters of Quel'Thalas.\"" }
entries[208700] = { ["name"] = "Battle Magister's Enchantments", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Battle Magister's Enchantment.\n\"The Magisters studied many years to protect Quel'Thalas and so weapons to bolster their skills were fashioned to assist that effort.\"" }
entries[208702] = { ["name"] = "Memory Essence", ["text"] = "Quest Item\n\"Essence of one of Gracus' most difficult memories.\"" }
entries[208704] = { ["name"] = "Deepdweller's Earthen Hearthstone", ["text"] = "Binds when picked up\nToy\nUse: Returns you to Hearthstone Location. Speak to an Innkeeper in a different place to change your home location.\n\"Composed of minerals extracted from the greatest of depths. Stones of similar nature are said to open a peculiar pathway to one's point of origin.\"" }
entries[208705] = { ["name"] = "Druidic Totem", ["text"] = "Quest Item\nUse: Place the totem to siphon magical energy from weakened, flame-corrupted Roottender Treants and Roottender Wildgrowths. (15 Sec Cooldown)" }
